fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    let mut result = Vec::with_capacity(a.len());
    
    for s in a {
        let mut lines = Vec::new();
        
        if keepends {
            // When keepends is true, we keep the line endings
            // We'll split by newline but include it in each line except possibly the last
            let mut current_line = String::new();
            for ch in s.chars() {
                current_line.push(ch);
                if ch == '\n' {
                    lines.push(current_line.clone());
                    current_line.clear();
                }
            }
            // Add any remaining content (last line without newline)
            if !current_line.is_empty() {
                lines.push(current_line);
            }
        } else {
            // When keepends is false, we remove line endings
            // Split by newline and filter out empty strings from consecutive newlines
            for line in s.split('\n') {
                lines.push(line.to_string());
            }
        }
        
        // Ensure the inner list is non-empty
        if lines.is_empty() {
            lines.push(String::new());
        }
        
        result.push(lines);
    }
    
    result
}